class Solution {
  public long shiftDistance(String s, String t, int[] nextCost, int[] previousCost) {
    long INF = Long.MAX_VALUE / 4;
    long[][] d = new long[26][26];
    for (long[] row : d) java.util.Arrays.fill(row, INF);
    for (int i = 0; i < 26; i++) {
      d[i][i] = 0;
      d[i][(i + 1) % 26] = Math.min(d[i][(i + 1) % 26], nextCost[i]);
      d[i][(i + 25) % 26] = Math.min(d[i][(i + 25) % 26], previousCost[i]);
    }
    for (int k = 0; k < 26; k++)
      for (int i = 0; i < 26; i++)
        for (int j = 0; j < 26; j++) d[i][j] = Math.min(d[i][j], d[i][k] + d[k][j]);
    long ans = 0;
    for (int i = 0; i < s.length(); i++) ans += d[s.charAt(i) - 'a'][t.charAt(i) - 'a'];
    return ans;
  }
}
